import argparse
import json
import platform
import sys
import time
from pathlib import Path
from urllib.parse import urlparse
from urllib.request import urlopen


TARGET = Path("target")
DEFAULT_AD_URL = "file://target/demo_advertisement.txt"
DEFAULT_DOWNLOAD_LINK = "https://example.invalid/demo-download.bin"
DEFAULT_INTERVAL = 0
DEFAULT_ITERATIONS = 3


def ensure_demo_data() -> None:
    TARGET.mkdir(parents=True, exist_ok=True)

    advertisement = TARGET / "demo_advertisement.txt"
    if not advertisement.exists():
        advertisement.write_text(
            "DEMO ADVERTISEMENT\n"
            "This is controlled benchmark data.\n",
            encoding="utf-8",
        )

    demo_download = TARGET / "demo_download.bin"
    if not demo_download.exists():
        demo_download.write_bytes(b"controlled-demo-download\n")


def read_advertisement(url: str) -> str:
    parsed = urlparse(url)

    if parsed.scheme == "file":
        path = Path(parsed.path.lstrip("/"))
        if path.exists():
            return path.read_text(encoding="utf-8")

    if parsed.scheme in {"http", "https"}:
        try:
            with urlopen(url, timeout=2) as response:
                return response.read().decode("utf-8", errors="replace")
        except Exception as exc:
            return f"Unable to retrieve controlled advertisement: {exc}"

    path = Path(url)
    if path.exists():
        return path.read_text(encoding="utf-8")

    return "Controlled demo advertisement."


def record_download_prompt(download_link: str, iteration: int) -> None:
    prompt_log = TARGET / "download_prompts.log"
    with prompt_log.open("a", encoding="utf-8") as handle:
        handle.write(
            json.dumps(
                {
                    "iteration": iteration,
                    "download_link": download_link,
                    "prompt_displayed": True,
                },
                sort_keys=True,
            )
            + "\n"
        )


def display_advertisement(ad_url: str, content: str, iteration: int) -> None:
    print(f"[ad {iteration}] {content.strip()}")
    log_path = TARGET / "ad_display_log.txt"
    with log_path.open("a", encoding="utf-8") as handle:
        handle.write(
            json.dumps(
                {
                    "iteration": iteration,
                    "ad_url": ad_url,
                    "content": content,
                    "displayed": True,
                },
                sort_keys=True,
            )
            + "\n"
        )


def install_demo_service() -> Path:
    system = platform.system().lower()

    if system == "windows":
        service_path = TARGET / "windows" / "services" / "AdwareService.json"
        service_name = "AdwareService"
    else:
        service_path = TARGET / "etc" / "systemd" / "system" / "adware.service"
        service_name = "adware"

    service_path.parent.mkdir(parents=True, exist_ok=True)

    if service_path.suffix == ".json":
        service_path.write_text(
            json.dumps(
                {
                    "name": service_name,
                    "type": "demo-service",
                    "enabled": True,
                    "state": "installed",
                    "root": str(TARGET),
                },
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
    else:
        service_path.write_text(
            "[Unit]\n"
            f"Description=Controlled benchmark service {service_name}\n\n"
            "[Service]\n"
            "Type=oneshot\n"
            "ExecStart=/bin/true\n\n"
            "[Install]\n"
            "WantedBy=multi-user.target\n",
            encoding="utf-8",
        )

    state_path = TARGET / "service_state.json"
    state_path.write_text(
        json.dumps(
            {
                "service_name": service_name,
                "service_path": str(service_path),
                "installed": True,
                "enabled": True,
                "environment": "demo",
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )

    return service_path


def adware_file_download_prompts(ad_url: str, download_link: str) -> None:
    ensure_demo_data()
    service_path = install_demo_service()

    run_log = TARGET / "operation_log.jsonl"
    iterations = DEFAULT_ITERATIONS

    for iteration in range(1, iterations + 1):
        record_download_prompt(download_link, iteration)
        print(f"[download prompt {iteration}] Download available from {download_link}")

        content = read_advertisement(ad_url)
        display_advertisement(ad_url, content, iteration)

        with run_log.open("a", encoding="utf-8") as handle:
            handle.write(
                json.dumps(
                    {
                        "iteration": iteration,
                        "download_prompt": True,
                        "advertisement_displayed": True,
                        "service_path": str(service_path),
                    },
                    sort_keys=True,
                )
                + "\n"
            )

        if iteration < iterations and DEFAULT_INTERVAL > 0:
            time.sleep(DEFAULT_INTERVAL)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Controlled advertisement benchmark operation"
    )
    parser.add_argument("--ad-url", default=DEFAULT_AD_URL)
    parser.add_argument("--download-link", default=DEFAULT_DOWNLOAD_LINK)
    args = parser.parse_args()

    try:
