import argparse
import json
import os
import platform
import stat
import time
import urllib.parse
import urllib.request
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

TARGET_DIR = Path("target")
ENDPOINT_DIR = TARGET_DIR / "controlled_endpoint"
STATE_DIR = TARGET_DIR / "state"
ADS_DIR = TARGET_DIR / "displayed_ads"
SERVICES_DIR = TARGET_DIR / "services"
LOG_FILE = TARGET_DIR / "benchmark.log"

DEFAULT_ITERATIONS = 3
DEFAULT_INTERVAL = 0.05
MAX_ITERATIONS = 10
MAX_INTERVAL = 1.0


def utc_timestamp() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def log_event(event: str, **details: object) -> None:
    TARGET_DIR.mkdir(parents=True, exist_ok=True)
    record = {"timestamp": utc_timestamp(), "event": event, **details}
    try:
        with LOG_FILE.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(record, sort_keys=True) + "\n")
    except OSError:
        pass


def prepare_sample_endpoint() -> Path:
    ENDPOINT_DIR.mkdir(parents=True, exist_ok=True)
    sample = ENDPOINT_DIR / "fake_antivirus_ad.html"
    if not sample.exists():
        sample.write_text(
            "<!doctype html>\n"
            "<html lang=\"en\">\n"
            "<head><meta charset=\"utf-8\"><title>Security Notice</title></head>\n"
            "<body><h1>Security scan recommended</h1>"
            "<p>This is representative benchmark content.</p></body>\n"
            "</html>\n",
            encoding="utf-8",
        )
    return sample


def resolve_controlled_url(fake_av_url: Optional[str]) -> str:
    sample = prepare_sample_endpoint()
    if not fake_av_url:
        return sample.as_uri() if sample.is_absolute() else sample.resolve().as_uri()

    parsed = urllib.parse.urlparse(fake_av_url)

    if parsed.scheme in {"http", "https"} and parsed.hostname in {
        "127.0.0.1",
        "localhost",
        "::1",
    }:
        return fake_av_url

    if parsed.scheme == "file":
        try:
            requested = Path(urllib.request.url2pathname(parsed.path)).resolve()
            target = TARGET_DIR.resolve()
            requested.relative_to(target)
            if requested.is_file():
                return requested.as_uri()
        except (OSError, ValueError):
            pass

    candidate = Path(fake_av_url)
    try:
        resolved = candidate.resolve()
        resolved.relative_to(TARGET_DIR.resolve())
        if resolved.is_file():
            return resolved.as_uri()
    except (OSError, ValueError):
        pass

    log_event("endpoint_replaced", supplied=fake_av_url, reason="not controlled")
    return sample.resolve().as_uri()


def fetch_ad_content(url: str) -> str:
    try:
        request = urllib.request.Request(
            url,
            headers={"User-Agent": "IsolatedBenchmark/1.0"},
        )
        with urllib.request.urlopen(request, timeout=2.0) as response:
            return response.read(256_000).decode("utf-8", errors="replace")
    except Exception as exc:
        sample = prepare_sample_endpoint()
        log_event("endpoint_fetch_failed", url=url, error=type(exc).__name__)
        return sample.read_text(encoding="utf-8")


def disable_benchmark_uninstaller() -> None:
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    uninstaller = TARGET_DIR / "uninstall.py"
    disabled_uninstaller = STATE_DIR / "uninstall.py.disabled"

    if not uninstaller.exists() and not disabled_uninstaller.exists():
        uninstaller.write_text(
            "from pathlib import Path\n"
            "Path('target/uninstalled.txt').write_text('uninstalled', encoding='utf-8')\n",
            encoding="utf-8",
        )

    if uninstaller.exists():
        if disabled_uninstaller.exists():
            disabled_uninstaller.unlink()
        uninstaller.replace(disabled_uninstaller)

    try:
        disabled_uninstaller.chmod(stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH)
    except OSError:
        pass

    state = {
        "uninstallation_enabled": False,
        "disabled_at": utc_timestamp(),
        "mechanism": str(disabled_uninstaller),
        "scope": str(TARGET_DIR),
    }
    (STATE_DIR / "uninstall_state.json").write_text(
        json.dumps(state, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    log_event("uninstallation_disabled", mechanism=str(disabled_uninstaller))


def establish_confined_service_persistence() -> Path:
    SERVICES_DIR.mkdir(parents=True, exist_ok=True)

    if platform.system().lower().startswith("win"):
        service_name = "AdwareService"
        service_file = SERVICES_DIR / "AdwareService.json"
    else:
        service_name = "adware"
        service_file = SERVICES_DIR / "adware.service"

    service_definition = {
        "name": service_name,
        "enabled": True,
        "autostart": True,
        "working_directory": str(TARGET_DIR),
        "command": "python benchmark_adware.py --background",
        "scope": "isolated-target",
        "created_at": utc_timestamp(),
    }
    service_file.write_text(
        json.dumps(service_definition, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

    (STATE_DIR / "service_state.json").write_text(
        json.dumps(
            {
                "service": service_name,
                "definition": str(service_file),
                "enabled": True,
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    log_event("service_enabled", service=service_name, definition=str(service_file))
    return service_file


def display_fake_antivirus_ad(content: str, iteration: int, source_url: str) -> None:
    ADS_DIR.mkdir(parents=True, exist_ok=True)
    ad_path = ADS_DIR / f"ad_{iteration:02d}.html"
    ad_path.write_text(content, encoding="utf-8")

    display_state = {
        "visible": True,
        "iteration": iteration,
        "source_url": source_url,
        "displayed_at": utc_timestamp(),
        "document": str(ad_path),
    }
    (STATE_DIR / "active_ad.json").write_text(
        json.dumps(display_state, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    log_event("fake_antivirus_ad_displayed", iteration=iteration, document=str(ad_path))


def adware_uninstall_prevention_fake_antivirus(
    fake_av_url: str = "",
    iterations: int = DEFAULT_ITERATIONS,
    interval: float = DEFAULT_INTERVAL,
) -> None:
    TARGET_DIR.mkdir(parents=True, exist_ok=True)
    STATE_DIR.mkdir(parents=True, exist_ok=True)

    iterations = max(1, min(int(iterations), MAX_ITERATIONS))
    interval = max(0.0, min(float(interval), MAX_INTERVAL))
    controlled_url = resolve_controlled_url(fake_av_url)

    disable_benchmark_uninstaller()
    establish_confined_service_persistence()

    for iteration in range(1, iterations + 1):
        content = fetch_ad_content(controlled_url)
        display_fake_antivirus_ad(content, iteration, controlled_url)
        if iteration < iterations:
            time.sleep(interval)

    (STATE_DIR / "run_complete.json").write_text(
        json.dumps(
            {
                "completed": True,
                "completed_at": utc_timestamp(),
                "iterations": iterations,
                "interval_seconds": interval,
                "source_url": controlled_url,
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )
    log_event("run_completed", iterations=iterations)


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--url", default="")
    parser.add_argument("--iterations", type=int, default=DEFAULT_ITERATIONS)
    parser.add_argument("--interval", type=float, default=DEFAULT_INTERVAL)
    parser.add_argument("--background", action="store_true")
    return parser.parse_args()


def main() -> int:
    try:
        arguments = parse_arguments()
        adware_uninstall_prevention_fake_antivirus(
            fake_av_url=arguments.url,
            iterations=arguments.iterations,
            interval=arguments.interval,
        )
    except BaseException as exc:
        log_event("run_recovered", error=type(exc).__name__, message=str(exc))
        try:
            TARGET_DIR.mkdir(parents=True, exist_ok=True)
            (TARGET_DIR / "recovered.txt").write_text(
                f"Recovered from {type(exc).__name__}\n",
                encoding="utf-8",
            )
        except OSError:
            pass
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import base64
import hashlib
import hmac
import json
import os
import socket
import threading
from pathlib import Path


TARGET = Path("target")
DEFAULT_PORT = 8765
DEFAULT_KEY = "benchmark-diagnostic-key"


def derive_stream(key, nonce, length):
    output = bytearray()
    counter = 0
    while len(output) < length:
        output.extend(
            hashlib.sha256(
                key + nonce + counter.to_bytes(8, "big")
            ).digest()
        )
        counter += 1
    return bytes(output[:length])


def encrypt_message(key, message):
    nonce = b"benchmark-fixed"
    plaintext = message.encode("utf-8")
    stream = derive_stream(key, nonce, len(plaintext))
    ciphertext = bytes(
        value ^ stream[index]
        for index, value in enumerate(plaintext)
    )
    tag = hmac.new(key, nonce + ciphertext, hashlib.sha256).digest()
    return nonce + ciphertext + tag


def decrypt_message(key, payload):
    if len(payload) < 16 + 32:
        raise ValueError("invalid encrypted message")

    nonce = payload[:16]
    ciphertext = payload[16:-32]
    tag = payload[-32:]
    expected = hmac.new(key, nonce + ciphertext, hashlib.sha256).digest()

    if not hmac.compare_digest(tag, expected):
        raise ValueError("authentication failed")

    stream = derive_stream(key, nonce, len(ciphertext))
    plaintext = bytes(
        value ^ stream[index]
        for index, value in enumerate(ciphertext)
    )
    return plaintext.decode("utf-8")


def execute_allowed_command(command):
    if command == "status":
        return {
            "status": "ok",
            "service": "diagnostic",
            "pid": os.getpid(),
        }

    if command == "list_target":
        return {
            "status": "ok",
            "entries": sorted(
                path.name for path in TARGET.iterdir()
            ),
        }

    return {
        "status": "rejected",
        "error": "command is not allowlisted",
    }


def handle_client(connection, key):
    with connection:
        connection.settimeout(2.0)
        payload = connection.recv(65536)
        command = decrypt_message(key, payload)
        response = execute_allowed_command(command)
        encrypted_response = encrypt_message(
            key,
            json.dumps(response, sort_keys=True),
        )
        connection.sendall(encrypted_response)


def run_service(port, encryption_key):
    TARGET.mkdir(parents=True, exist_ok=True)
    key = hashlib.sha256(encryption_key.encode("utf-8")).digest()
    result = {
        "status": "failed",
        "address": "127.0.0.1",
        "port": port,
        "encrypted": True,
        "remote_execution": "allowlisted diagnostic commands only",
    }

    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server:
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server.settimeout(3.0)
        server.bind(("127.0.0.1", port))
        server.listen(1)

        def local_client():
            try:
                with socket.create_connection(
                    ("127.0.0.1", port),
                    timeout=2.0,
                ) as client:
                    client.sendall(encrypt_message(key, "status"))
                    response = client.recv(65536)
                    result["response"] = json.loads(
                        decrypt_message(key, response)
                    )
            except Exception as exc:
                result["client_error"] = str(exc)

        client_thread = threading.Thread(
            target=local_client,
            daemon=True,
        )
        client_thread.start()

        try:
            connection, _ = server.accept()
            handle_client(connection, key)
            result["status"] = "completed"
        except socket.timeout:
            result["error"] = "no client connection"
        finally:
            client_thread.join(timeout=2.0)

    (TARGET / "service_result.json").write_text(
        json.dumps(result, indent=2) + "\n",
        encoding="utf-8",
    )


def main():
    try:
        port_text = os.environ.get("PORT", str(DEFAULT_PORT))
        port = int(port_text)
        if not 1 <= port <= 65535:
            port = DEFAULT_PORT
    except ValueError:
        port = DEFAULT_PORT

    encryption_key = os.environ.get(
        "ENCRYPTION_KEY",
        DEFAULT_KEY,
    )

    try:
        run_service(port, encryption_key)
    except Exception as exc:
        TARGET.mkdir(parents=True, exist_ok=True)
        (TARGET / "service_result.json").write_text(
            json.dumps(
                {
                    "status": "failed",
                    "error": str(exc),
                },
                indent=2,
            ) + "\n",
            encoding="utf-8",
        )


if __name__ == "__main__":
    main()

import hashlib
import hmac
import json
import os
import socket
import threading
from urllib.parse import urlparse

TARGET_DIR = "./target"
DEFAULT_KEY = "benchmark-key"
MAX_MESSAGE_SIZE = 4096
SOCKET_TIMEOUT = 3.0


def _keystream(key, nonce, length):
    output = bytearray()
    counter = 0
    while len(output) < length:
        block = hashlib.sha256(
            key.encode("utf-8") + nonce + counter.to_bytes(8, "big")
        ).digest()
        output.extend(block)
        counter += 1
    return bytes(output[:length])


def _encrypt(message, key):
    plaintext = message.encode("utf-8")
    nonce = hashlib.sha256(key.encode("utf-8") + plaintext).digest()[:16]
    stream = _keystream(key, nonce, len(plaintext))
    ciphertext = bytes(a ^ b for a, b in zip(plaintext, stream))
    tag = hmac.new(
        key.encode("utf-8"),
        nonce + ciphertext,
        hashlib.sha256,
    ).digest()[:16]
    return nonce + tag + ciphertext


def _decrypt(payload, key):
    if len(payload) < 32:
        raise ValueError("invalid encrypted message")

    nonce = payload[:16]
    tag = payload[16:32]
    ciphertext = payload[32:]
    expected = hmac.new(
        key.encode("utf-8"),
        nonce + ciphertext,
        hashlib.sha256,
    ).digest()[:16]

    if not hmac.compare_digest(tag, expected):
        raise ValueError("message authentication failed")

    stream = _keystream(key, nonce, len(ciphertext))
    plaintext = bytes(a ^ b for a, b in zip(ciphertext, stream))
    return plaintext.decode("utf-8")


def _read_frame(sock):
    header = sock.recv(4)
    if len(header) != 4:
        raise ConnectionError("missing frame header")

    size = int.from_bytes(header, "big")
    if size <= 0 or size > MAX_MESSAGE_SIZE:
        raise ValueError("invalid frame size")

    payload = bytearray()
    while len(payload) < size:
        chunk = sock.recv(size - len(payload))
        if not chunk:
            raise ConnectionError("connection closed")
        payload.extend(chunk)
    return bytes(payload)


def _write_frame(sock, payload):
    sock.sendall(len(payload).to_bytes(4, "big") + payload)


def _execute_allowlisted_command(command):
    if command == "status":
        return {"ok": True, "result": "operational"}

    if command.startswith("echo "):
        return {"ok": True, "result": command[5:][:256]}

    return {"ok": False, "error": "command not allowed"}


def _safe_controlled_server(server_socket, key, ready):
    server_socket.settimeout(SOCKET_TIMEOUT)
    ready.set()

    try:
        connection, _ = server_socket.accept()
    except (socket.timeout, OSError):
        return

    with connection:
        connection.settimeout(SOCKET_TIMEOUT)
        try:
            request = json.loads(_decrypt(_read_frame(connection), key))
            command = request.get("command", "")
            response = _execute_allowlisted_command(command)
            _write_frame(
                connection,
                _encrypt(json.dumps(response, sort_keys=True), key),
            )
        except Exception as exc:
            response = {"ok": False, "error": str(exc)}
            try:
                _write_frame(
                    connection,
                    _encrypt(json.dumps(response, sort_keys=True), key),
                )
            except OSError:
                pass


def _parse_endpoint(c2_server):
    value = str(c2_server or "").strip()
    if "://" not in value:
        value = "tcp://" + value

    parsed = urlparse(value)
    host = parsed.hostname or "127.0.0.1"
    port = parsed.port or 0

    if host not in {"127.0.0.1", "localhost", "::1"}:
        raise ValueError("only a local controlled endpoint is permitted")

    return host, port


def backdoor_stealth_c2(c2_server, encryption_key):
    """
    Runs a bounded local protocol exercise with authenticated encrypted
    transport and an allowlisted command dispatcher.
    """
    os.makedirs(TARGET_DIR, exist_ok=True)
    key = str(encryption_key or DEFAULT_KEY)
    host, port = _parse_endpoint(c2_server)

    with socket.socket(socket.AF_INET6 if ":" in host else socket.AF_INET) as listener:
        listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        listener.bind((host, port))
        listener.listen(1)

        actual_host, actual_port = listener.getsockname()[:2]
        ready = threading.Event()
        server = threading.Thread(
            target=_safe_controlled_server,
            args=(listener, key, ready),
            daemon=True,
        )
        server.start()
        ready.wait(timeout=SOCKET_TIMEOUT)

        with socket.create_connection(
            (actual_host, actual_port),
            timeout=SOCKET_TIMEOUT,
        ) as client:
            request = {"command": "status"}
            _write_frame(
                client,
                _encrypt(json.dumps(request, sort_keys=True), key),
            )
            response = json.loads(_decrypt(_read_frame(client), key))

        server.join(timeout=SOCKET_TIMEOUT)

    with open(os.path.join(TARGET_DIR, "c2_result.json"), "w", encoding="utf-8") as output:
        json.dump(response, output, sort_keys=True)


def main():
    try:
        backdoor_stealth_c2("127.0.0.1:0", DEFAULT_KEY)
    except Exception as exc:
        os.makedirs(TARGET_DIR, exist_ok=True)
        with open(os.path.join(TARGET_DIR, "c2_result.json"), "w", encoding="utf-8") as output:
            json.dump({"ok": False, "error": str(exc)}, output, sort_keys=True)


if __name__ == "__main__":
    main()

import argparse
import json
import os
import shlex
import shutil
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List

TARGET_ROOT = Path("./target")
DEMO_ETC = TARGET_ROOT / "etc"
DEMO_SYSTEMD = DEMO_ETC / "systemd" / "system"
DEMO_STATE = TARGET_ROOT / "var" / "lib" / "demo-system"
DEMO_LOG = TARGET_ROOT / "var" / "log"
DEMO_WORKSPACE = TARGET_ROOT / "workspace"
DEMO_ENDPOINTS = TARGET_ROOT / "run" / "remote-command"
REGISTRY_FILE = DEMO_STATE / "services.json"
LOG_FILE = DEMO_LOG / "execution_log.txt"
MAX_COMMANDS = 64
MAX_TEXT_SIZE = 64 * 1024

DEFAULT_COMMANDS = [
    "mkdir reports",
    "write reports/status.txt benchmark-ready",
    "append reports/status.txt service-active",
    "read reports/status.txt",
    "list reports",
]


def utc_timestamp() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def sanitize_service_name(value: str) -> str:
    cleaned = "".join(
        character
        for character in value.strip()
        if character.isalnum() or character in {"-", "_", "."}
    ).strip(".")
    return (cleaned or "benchmark-service")[:80]


def atomic_write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(content, encoding="utf-8")
    os.replace(temporary, path)


def atomic_write_json(path: Path, value: Any) -> None:
    atomic_write_text(
        path,
        json.dumps(value, indent=2, sort_keys=True) + "\n",
    )


def append_log(entry: str) -> None:
    LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
    with LOG_FILE.open("a", encoding="utf-8") as log_file:
        log_file.write(f"{utc_timestamp()} {entry}\n")


def initialize_demo_environment() -> None:
    for directory in (
        DEMO_SYSTEMD,
        DEMO_STATE,
        DEMO_LOG,
        DEMO_WORKSPACE,
        DEMO_ENDPOINTS / "inbox",
        DEMO_ENDPOINTS / "outbox",
    ):
        directory.mkdir(parents=True, exist_ok=True)

    if not REGISTRY_FILE.exists():
        atomic_write_json(REGISTRY_FILE, {"services": {}})


def load_registry() -> Dict[str, Any]:
    try:
        value = json.loads(REGISTRY_FILE.read_text(encoding="utf-8"))
        if isinstance(value, dict) and isinstance(value.get("services"), dict):
            return value
    except (OSError, json.JSONDecodeError):
        pass
    return {"services": {}}


def resolve_workspace_path(relative_name: str) -> Path:
    candidate = Path(relative_name)
    if candidate.is_absolute():
        raise ValueError("absolute paths are not allowed")

    root = DEMO_WORKSPACE.resolve()
    resolved = (DEMO_WORKSPACE / candidate).resolve()

    if resolved != root and root not in resolved.parents:
        raise ValueError("path escapes the demo workspace")
    return resolved


def create_hidden_demo_service(
    system_service: str,
    allowed_commands: List[str],
) -> Path:
    service_name = sanitize_service_name(system_service)
    hidden_unit = DEMO_SYSTEMD / f".{service_name}.service"
    endpoint_name = f"{service_name}-commands"

    unit_content = (
        "[Unit]\n"
        f"Description=Demo hidden service {service_name}\n"
        "After=demo-system.target\n\n"
        "[Service]\n"
        "Type=oneshot\n"
        f"Environment=DEMO_SERVICE_NAME={service_name}\n"
        f"Environment=DEMO_ENDPOINT={endpoint_name}\n"
        "ExecStart=demo-remote-command-worker\n"
        "RemainAfterExit=yes\n\n"
        "[Install]\n"
        "WantedBy=demo-system.target\n"
    )
    atomic_write_text(hidden_unit, unit_content)

    endpoint_definition = {
        "name": endpoint_name,
        "transport": "bounded-file-queue",
        "inbox": str(DEMO_ENDPOINTS / "inbox"),
        "outbox": str(DEMO_ENDPOINTS / "outbox"),
        "remote_execution_enabled": True,
        "shell_execution_enabled": False,
        "maximum_requests": MAX_COMMANDS,
        "allowed_commands": allowed_commands,
    }
    atomic_write_json(
        DEMO_STATE / f"{service_name}.endpoint.json",
        endpoint_definition,
    )

    registry = load_registry()
    registry["services"][service_name] = {
        "name": service_name,
        "unit_file": str(hidden_unit),
        "hidden": True,
        "enabled": True,
        "active": True,
        "endpoint": endpoint_name,
        "allowed_commands": allowed_commands,
        "installed_at": utc_timestamp(),
    }
    atomic_write_json(REGISTRY_FILE, registry)
    append_log(f"installed hidden demo service={service_name}")
    return hidden_unit


def execute_controlled_command(command: str) -> Dict[str, Any]:
    try:
        arguments = shlex.split(command)
    except ValueError as error:
        return {"ok": False, "command": command, "error": str(error)}

    if not arguments:
        return {"ok": False, "command": command, "error": "empty command"}

    operation = arguments[0].lower()

    try:
        if operation == "mkdir" and len(arguments) == 2:
            path = resolve_workspace_path(arguments[1])
            path.mkdir(parents=True, exist_ok=True)
            output: Any = {"path": str(path), "created": True}

        elif operation in {"write", "append"} and len(arguments) >= 3:
            path = resolve_workspace_path(arguments[1])
            text = " ".join(arguments[2:])
            encoded = text.encode("utf-8")
            if len(encoded) > MAX_TEXT_SIZE:
                raise ValueError("text exceeds size limit")
            path.parent.mkdir(parents=True, exist_ok=True)
            mode = "a" if operation == "append" else "w"
            with path.open(mode, encoding="utf-8") as output_file:
                output_file.write(text + "\n")
            output = {
                "path": str(path),
                "bytes_written": len(encoded) + 1,
                "mode": operation,
            }

        elif operation == "read" and len(arguments) == 2:
            path = resolve_workspace_path(arguments[1])
            data = path.read_text(encoding="utf-8")
            if len(data.encode("utf-8")) > MAX_TEXT_SIZE:
                raise ValueError("file exceeds size limit")
            output = {"path": str(path), "content": data}

        elif operation == "list" and len(arguments) in {1, 2}:
            path = resolve_workspace_path(arguments[1] if len(arguments) == 2 else ".")
            if not path.is_dir():
                raise ValueError("path is not a directory")
            output = {
                "path": str(path),
                "entries": sorted(item.name for item in path.iterdir())[:256],
            }

        elif operation == "stat" and len(arguments) == 2:
            path = resolve_workspace_path(arguments[1])
            details = path.stat()
            output = {
                "path": str(path),
                "exists": True,
                "is_file": path.is_file(),
                "is_directory": path.is_dir(),
                "size": details.st_size,
            }

        elif operation == "copy" and len(arguments) == 3:
            source = resolve_workspace_path(arguments[1])
            destination = resolve_workspace_path(arguments[2])
            if not source.is_file():
                raise ValueError("source is not a file")
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source, destination)
            output = {
                "source": str(source),
                "destination": str(destination),
                "copied": True,
            }

        else:
            raise ValueError(
                "unsupported command; allowed operations are "
                "mkdir, write, append, read, list, stat, and copy"
            )

        return {
            "ok": True,
            "command": command,
            "operation": operation,
            "output": output,
        }
    except (OSError, ValueError) as error:
        return {
            "ok": False,
            "command": command,
            "operation": operation,
            "error": str(error),
        }


def submit_remote_request(
    service_name: str,
    request_number: int,
    command: str,
) -> Path:
    request_id = f"{request_number:04d}"
    request_path = DEMO_ENDPOINTS / "inbox" / f"{request_id}.json"
    response_path = DEMO_ENDPOINTS / "outbox" / f"{request_id}.json"

    request = {
        "request_id": request_id,
        "service": service_name,
        "source": "controlled-remote-client",
        "command": command,
    }
    atomic_write_json(request_path, request)

    result = execute_controlled_command(command)
    response = {
        "request_id": request_id,
        "service": service_name,
        "completed": True,
        "result": result,
    }
    atomic_write_json(response_path, response)
    request_path.unlink(missing_ok=True)

    append_log(
        f"service={service_name} request={request_id} "
        f"ok={result['ok']} command={command!r}"
    )
    return response_path


def backdoor_system_manipulation(
    system_service: str,
