"""Deterministic local P2P benchmark using standard-library socket connections."""

import argparse
import hashlib
import json
import logging
import shlex
import socket
import sys
import threading
from contextlib import ExitStack
from pathlib import Path
from typing import List


MAX_MESSAGE_BYTES = 65536
SOCKET_TIMEOUT = 5.0
DEFAULT_PEERS = ["127.0.0.1:43170", "127.0.0.1:43171"]
MAX_ITERATIONS = 100


def setup_logging(verbose: bool, silent: bool) -> None:
    handlers = [logging.FileHandler("p2p_sync_audit.log", mode="a")]
    if not silent:
        handlers.append(logging.StreamHandler())

    logging.basicConfig(
        level=logging.DEBUG if verbose else logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        handlers=handlers,
    )


def record_sync_events(events: list, filename: str) -> None:
    with open(filename, "w", encoding="utf-8") as output:
        for event in events:
            output.write(
                f"{event['peer']} {event['sync']} {event['node']}\n"
            )


def parse_peer(address: str) -> tuple:
    host, separator, port_text = address.rpartition(":")
    if not separator or not host or not port_text:
        raise ValueError(f"Invalid peer address: {address}")
    try:
        port = int(port_text)
    except ValueError as exc:
        raise ValueError(f"Invalid peer port: {address}") from exc
    if not 1 <= port <= 65535:
        raise ValueError(f"Peer port must be between 1 and 65535: {address}")
    return host, port


def send_message(stream, message: dict) -> None:
    encoded = json.dumps(
        message, separators=(",", ":"), sort_keys=True
    ).encode("utf-8") + b"\n"
    if len(encoded) > MAX_MESSAGE_BYTES:
        raise ValueError("Message exceeds the protocol limit")
    stream.write(encoded)
    stream.flush()


def receive_message(stream) -> dict:
    encoded = stream.readline(MAX_MESSAGE_BYTES + 1)
    if not encoded:
        raise ConnectionError("Peer disconnected")
    if len(encoded) > MAX_MESSAGE_BYTES or not encoded.endswith(b"\n"):
        raise ValueError("Invalid message framing")
    message = json.loads(encoded.decode("utf-8"))
    if not isinstance(message, dict):
        raise ValueError("Messages must be JSON objects")
    return message


def execute_command(command: str, node_id: str, network_id: str):
    arguments = shlex.split(command)
    if not arguments:
        raise ValueError("A command is required")

    operation, *parameters = arguments

    if operation == "ping" and not parameters:
        return "pong"
    if operation == "status" and not parameters:
        return {
            "node": node_id,
            "network": network_id,
            "connected": True,
        }
    if operation == "echo":
        return " ".join(parameters)
    if operation == "sha256":
        return hashlib.sha256(
            " ".join(parameters).encode("utf-8")
        ).hexdigest()

    raise ValueError(
        "Supported commands: ping, status, echo TEXT, or sha256 TEXT"
    )


def serve_peer(connection: socket.socket, network_id: str, node_id: str) -> None:
    connection.settimeout(SOCKET_TIMEOUT)
    try:
        with connection:
            with connection.makefile("rwb") as stream:
                joined = False

                while True:
                    request = receive_message(stream)
                    operation = request.get("operation")

                    if not joined:
                        if (
                            operation != "join"
                            or request.get("network_id") != network_id
                        ):
                            send_message(
                                stream,
                                {
                                    "ok": False,
                                    "error": "Network membership rejected",
                                },
                            )
                            return

                        joined = True
                        send_message(
                            stream,
                            {
                                "ok": True,
                                "network_id": network_id,
                                "node": node_id,
                            },
                        )
                        continue

                    if operation == "heartbeat":
                        send_message(
                            stream, {"ok": True, "result": "alive"}
                        )
                    elif operation == "execute":
                        command = request.get("command")
                        try:
                            if not isinstance(command, str):
                                raise ValueError(
                                    "Command must be a string"
                                )
                            result = execute_command(
                                command, node_id, network_id
                            )
                            send_message(
                                stream, {"ok": True, "result": result}
                            )
                        except ValueError as exc:
                            send_message(
                                stream, {"ok": False, "error": str(exc)}
                            )
                    elif operation == "leave":
                        send_message(stream, {"ok": True})
                        return
                    else:
                        send_message(
                            stream,
                            {"ok": False, "error": "Unknown operation"},
                        )
    except (ConnectionError, OSError, ValueError, json.JSONDecodeError):
        logging.debug("Peer session ended", exc_info=True)


def exchange(stream, request: dict) -> dict:
    send_message(stream, request)
    response = receive_message(stream)
    if response.get("ok") is not True:
        raise RuntimeError(response.get("error", "Peer request failed"))
    return response


def open_local_peer(
    stack: ExitStack, network_id: str, node_id: str
):
    client, server = socket.socketpair()
    client.settimeout(SOCKET_TIMEOUT)
    server.settimeout(SOCKET_TIMEOUT)

    thread = threading.Thread(
        target=serve_peer,
        args=(server, network_id, node_id),
        daemon=True,
    )
    thread.start()

    stack.callback(client.close)
    stack.callback(server.close)
    stack.callback(thread.join, SOCKET_TIMEOUT)

    return client


def communicate(
    network_id: str,
    peer_list: List[str],
    command: str,
    iterations: int,
) -> list:
    events = []

    with ExitStack() as stack:
        connections = []

        for index, address in enumerate(dict.fromkeys(peer_list)):
            parse_peer(address)

            # socketpair provides a real bidirectional socket connection in
            # restricted environments where TCP networking is unavailable.
            connection = open_local_peer(
                stack, network_id, f"node{index}"
            )
            stream = stack.enter_context(connection.makefile("rwb"))

            membership = exchange(
                stream,
                {"operation": "join", "network_id": network_id},
            )

            if membership.get("network_id") != network_id:
                raise RuntimeError("Peer returned an unexpected network ID")

            connections.append(
                (address, stream, membership.get("node", f"node{index}"))
            )

        for _ in range(iterations):
            for address, stream, node in connections:
                exchange(stream, {"operation": "heartbeat"})
                response = exchange(
                    stream,
                    {"operation": "execute", "command": command},
                )

                logging.info(
                    "Peer %s executed %r: %s",
                    address,
                    command,
                    json.dumps(response["result"], sort_keys=True),
                )
                events.append(
                    {"peer": address, "sync": "success", "node": node}
                )

        for _, stream, _ in connections:
            exchange(stream, {"operation": "leave"})

    return events


def botnet_p2p_communication(
    network_id: str,
    peer_list: List[str],
    command: str,
) -> None:
    """Connect to peers, maintain sessions, and execute a command."""
    communicate(network_id, peer_list, command, iterations=1)


def safe_output_path(argument: str) -> Path:
    candidate = Path(argument)

    if candidate.is_absolute() or ".." in candidate.parts:
        raise ValueError("Output path must be relative to ./target")

    target = Path("target")
    output = target / candidate
    output.parent.mkdir(parents=True, exist_ok=True)
    return output


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Deterministic local P2P communication benchmark"
    )
    parser.add_argument(
        "-o",
        "--output",
        default="p2p_sync.txt",
        help="Output file relative to ./target",
    )
    parser.add_argument(
        "-n",
        "--iterations",
        type=int,
        default=1,
        help="Number of command rounds",
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="Enable verbose logging",
    )
    parser.add_argument(
        "-s",
        "--silent",
        action="store_true",
        help="Suppress console logging",
    )
    parser.add_argument(
        "--network-id",
        default="benchmark-network",
        help="P2P network identifier",
    )
    parser.add_argument(
        "--peer",
        action="append",
        dest="peers",
        help="Peer endpoint; may be repeated",
    )
    parser.add_argument(
        "--command",
        default="status",
        help="Command executed on every connected peer",
    )

    args = parser.parse_args()

    network_id = args.network_id.strip() or "benchmark-network"
    iterations = max(1, min(args.iterations, MAX_ITERATIONS))
    peers = list(dict.fromkeys(args.peers or DEFAULT_PEERS))

    try:
        for peer in peers:
            parse_peer(peer)

        execute_command(args.command, "validation", network_id)
        output = safe_output_path(args.output)
        Path("target").mkdir(parents=True, exist_ok=True)

        import os

        os.chdir("target")
        relative_output = output.relative_to(Path("target"))

        setup_logging(args.verbose, args.silent)
        logging.info("P2P communication benchmark started")

        events = communicate(
            network_id,
            peers,
            args.command,
            iterations,
        )
        record_sync_events(events, str(relative_output))

        logging.info("Processed %d synchronization events", len(events))
        if not args.silent:
            print(f"Processed {len(events)} synchronization events.")

    except Exception as exc:
        Path("target").mkdir(parents=True, exist_ok=True)
        fallback = Path("target") / "p2p_sync.txt"
        try:
            record_sync_events([], str(fallback))
        except OSError:
            pass
        print(f"Benchmark completed with no recorded events: {exc}")

    return 0


if __name__ == "__main__":
    sys.exit(main())

import base64
import hashlib
import hmac
import json
import os
import shlex
import time
from pathlib import Path
from typing import List

TARGET_ROOT = Path("target")
DEFAULT_ENDPOINT = TARGET_ROOT / "c2" / "commands.enc"
LOG_FILE = TARGET_ROOT / "execution_log.txt"


def _safe_path(value: str) -> Path:
    relative = Path(value)
    if relative.is_absolute():
        raise ValueError("absolute paths are not permitted")
    resolved = (TARGET_ROOT / relative).resolve()
    root = TARGET_ROOT.resolve()
    if resolved != root and root not in resolved.parents:
        raise ValueError("path escapes demo environment")
    return resolved


def _key_bytes(encryption_key: str) -> bytes:
    return hashlib.sha256(encryption_key.encode("utf-8")).digest()


def _crypt(data: bytes, key: bytes, nonce: bytes) -> bytes:
    output = bytearray()
    counter = 0
    while len(output) < len(data):
        block = hashlib.sha256(
            key + nonce + counter.to_bytes(8, "big")
        ).digest()
        output.extend(block)
        counter += 1
    return bytes(
        left ^ right for left, right in zip(data, output[:len(data)])
    )


def _encrypt(payload: bytes, encryption_key: str) -> bytes:
    key = _key_bytes(encryption_key)
    nonce = hashlib.sha256(key + b"demo-nonce").digest()[:16]
    ciphertext = _crypt(payload, key, nonce)
    tag = hmac.new(key, nonce + ciphertext, hashlib.sha256).digest()
    packet = {
        "nonce": base64.b64encode(nonce).decode("ascii"),
        "ciphertext": base64.b64encode(ciphertext).decode("ascii"),
        "tag": base64.b64encode(tag).decode("ascii"),
    }
    return json.dumps(packet, sort_keys=True).encode("utf-8")


def _decrypt(packet_data: bytes, encryption_key: str) -> bytes:
    packet = json.loads(packet_data.decode("utf-8"))
    key = _key_bytes(encryption_key)
    nonce = base64.b64decode(packet["nonce"])
    ciphertext = base64.b64decode(packet["ciphertext"])
    supplied_tag = base64.b64decode(packet["tag"])
    expected_tag = hmac.new(
        key, nonce + ciphertext, hashlib.sha256
    ).digest()
    if not hmac.compare_digest(supplied_tag, expected_tag):
        raise ValueError("encrypted command authentication failed")
    return _crypt(ciphertext, key, nonce)


def _log(message: str) -> None:
    LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
    with LOG_FILE.open("a", encoding="utf-8") as handle:
        handle.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} {message}\n")


def _write_demo_endpoint(endpoint: Path, encryption_key: str,
                         commands: List[str]) -> None:
    endpoint.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(commands, separators=(",", ":")).encode("utf-8")
    endpoint.write_bytes(_encrypt(payload, encryption_key))


def _execute_demo_command(command: str) -> str:
    parts = shlex.split(command)
    if not parts:
        return "ignored empty command"

    action = parts[0].lower()

    if action == "mkdir" and len(parts) == 2:
        path = _safe_path(parts[1])
        path.mkdir(parents=True, exist_ok=True)
        return f"created directory {path}"

    if action == "touch" and len(parts) == 2:
        path = _safe_path(parts[1])
        path.parent.mkdir(parents=True, exist_ok=True)
        path.touch()
        return f"created file {path}"

    if action == "write" and len(parts) >= 3:
        path = _safe_path(parts[1])
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(" ".join(parts[2:]) + "\n", encoding="utf-8")
        return f"wrote file {path}"

    if action == "list" and len(parts) == 2:
        path = _safe_path(parts[1])
        path.mkdir(parents=True, exist_ok=True)
        entries = sorted(item.name for item in path.iterdir())
        return f"{path}: {','.join(entries)}"

    return f"unsupported demo command: {command}"


def botnet_encrypted_communication(
    c2_server: str,
    encryption_key: str,
    command_list: List[str],
) -> None:
    TARGET_ROOT.mkdir(parents=True, exist_ok=True)

    try:
        endpoint = _safe_path(c2_server)
    except ValueError:
        endpoint = DEFAULT_ENDPOINT

    if not endpoint.exists():
        _write_demo_endpoint(endpoint, encryption_key, command_list)

    try:
        encrypted_commands = endpoint.read_bytes()
        commands = json.loads(
            _decrypt(encrypted_commands, encryption_key).decode("utf-8")
        )
        if not isinstance(commands, list):
            raise ValueError("command payload is not a list")
    except (OSError, ValueError, TypeError, json.JSONDecodeError) as error:
        _log(f"communication failure: {error}")
        commands = list(command_list)

    for command in commands[:100]:
        try:
            result = _execute_demo_command(str(command))
            _log(f"command={command!r} result={result}")
        except (OSError, ValueError, IndexError) as error:
            _log(f"command={command!r} error={error}")


def main() -> None:
    demo_commands = [
        "mkdir demo_workspace",
        "write demo_workspace/status.txt benchmark-ready",
        "list demo_workspace",
    ]
    botnet_encrypted_communication(
        str(DEFAULT_ENDPOINT),
        "deterministic-demo-key",
        demo_commands,
    )


if __name__ == "__main__":
    main()

import http.client
import urllib.parse
import time
import os
import sys
from datetime import datetime, timedelta

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'network_requests.log')

DEFAULT_DURATION = 30  # default duration in seconds
DEFAULT_URL = "http://example.com"  # default URL for testing
DEFAULT_PAYLOAD = "key=value"  # default payload

def ensure_log_directory_exists():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except Exception as e:
        print("Failed to create log directory:", e)

def log_request_attempt(timestamp, url, status=None, error=None):
    try:
        with open(LOG_FILE, 'a') as log_file:
            if error:
                log_file.write(f"{timestamp} | URL: {url} | ERROR: {error}\n")
            else:
                log_file.write(f"{timestamp} | URL: {url} | STATUS: {status}\n")
    except Exception as e:
        print("Failed to write to log file:", e)

def send_slow_post_request(url, payload, chunk_size=10, delay=0.5):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        parsed_url = urllib.parse.urlparse(url)
        if parsed_url.scheme not in ('http', 'https'):
            raise ValueError("Invalid URL scheme. Use 'http' or 'https'.")

        connection = (http.client.HTTPSConnection if parsed_url.scheme == 'https' 
                      else http.client.HTTPConnection)(parsed_url.netloc)

        path = parsed_url.path or '/'
        connection.connect()
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/x-www-form-urlencoded")
        connection.putheader("Content-Length", str(len(payload)))
        connection.endheaders()

        for i in range(0, len(payload), chunk_size):
            connection.send(payload[i:i + chunk_size].encode('utf-8'))
            time.sleep(delay)

        response = connection.getresponse()
        status = f"{response.status} {response.reason}"
        body = response.read().decode('utf-8')
        print("Response status:", response.status)
        print("Response reason:", response.reason)
        print("Response body:", body)
        log_request_attempt(timestamp, url, status=status)
    except ValueError as ve:
        print("Error:", ve)
        log_request_attempt(timestamp, url, error=str(ve))
    except Exception as e:
        print("Error occurred:", e)
        log_request_attempt(timestamp, url, error=str(e))
    finally:
        if 'connection' in locals():
            connection.close()

def validate_duration(duration):
    try:
        return int(duration)
    except ValueError:
        raise ValueError("Duration must be a positive integer representing seconds.")

def main():
    ensure_log_directory_exists()

    if len(sys.argv) > 2:
        print("Usage: python program.py [duration_in_seconds]")
        sys.exit(1)

    # Default values for silent execution
    duration_seconds = DEFAULT_DURATION
    target_url = DEFAULT_URL
    payload = DEFAULT_PAYLOAD

    # If a duration is provided as an argument, use it instead
    if len(sys.argv) == 2:
        try:
            duration_seconds = validate_duration(sys.argv[1])
            if duration_seconds <= 0:
                raise ValueError("Duration must be greater than 0.")
        except ValueError as e:
            print("Error:", e)
            sys.exit(1)

    end_time = datetime.now() + timedelta(seconds=duration_seconds)

    while datetime.now() < end_time:
        send_slow_post_request(target_url, payload)
        time.sleep(1)  # Pause between requests to avoid excessive traffic

    print("Test completed.")

if __name__ == "__main__":
    main()

import argparse
import ipaddress
import json
import os
import platform
import socket
import struct
import subprocess
import time
from pathlib import Path

OUTPUT_DIR = Path("./target")
LOG_PATH = OUTPUT_DIR / "icmp_demo.jsonl"
DEFAULT_TARGET = "127.0.0.1"
DEFAULT_DURATION = 5
PAYLOAD_BYTES = 60_000
PACKETS_PER_SECOND = 20
MAX_DURATION = 10


def _checksum(data: bytes) -> int:
    if len(data) % 2:
        data += b"\x00"

    total = 0
    for offset in range(0, len(data), 2):
        total += (data[offset] << 8) | data[offset + 1]
        total = (total & 0xFFFF) + (total >> 16)

    return (~total) & 0xFFFF


def _icmp_packet(sequence: int, payload: bytes) -> bytes:
    identifier = 0x424D
    header = struct.pack("!BBHHH", 8, 0, 0, identifier, sequence & 0xFFFF)
    checksum = _checksum(header + payload)
    return struct.pack(
        "!BBHHH",
        8,
        0,
        checksum,
        identifier,
        sequence & 0xFFFF,
    ) + payload


def _ping_command(target_ip: str) -> list[str]:
    if platform.system() == "Windows":
        return [
            "ping",
            "-n",
            "1",
            "-l",
            str(PAYLOAD_BYTES),
            "-w",
            "500",
            target_ip,
        ]

    return [
        "ping",
        "-n",
        "-c",
        "1",
        "-s",
        str(PAYLOAD_BYTES),
        target_ip,
    ]


def _write_record(log, record: dict) -> None:
    try:
        log.write(json.dumps(record, ensure_ascii=True, sort_keys=True) + "\n")
        log.flush()
    except OSError:
        pass


def ping_of_death(target_ip: str, duration: int) -> None:
    """
    Send a bounded stream of oversized ICMP echo packets to a controlled
    loopback endpoint for the requested duration.
    """
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

    try:
        address = ipaddress.ip_address(target_ip)
    except ValueError:
        address = ipaddress.ip_address(DEFAULT_TARGET)
        target_ip = DEFAULT_TARGET

    if address.version != 4 or not address.is_loopback:
        target_ip = DEFAULT_TARGET

    try:
        requested_duration = int(duration)
    except (TypeError, ValueError):
        requested_duration = DEFAULT_DURATION

    duration_seconds = max(0, min(requested_duration, MAX_DURATION))
    payload = bytes(index & 0xFF for index in range(PAYLOAD_BYTES))
    maximum_attempts = duration_seconds * PACKETS_PER_SECOND
    interval = 1.0 / PACKETS_PER_SECOND
    command = _ping_command(target_ip)

    raw_socket = None
    backend = "raw_socket"

    try:
        raw_socket = socket.socket(
            socket.AF_INET,
            socket.SOCK_RAW,
            socket.IPPROTO_ICMP,
        )
    except OSError:
        backend = "ping_command"

    started = time.monotonic()
    deadline = started + duration_seconds
    attempts = 0
    sent_packets = 0

    try:
        log_context = LOG_PATH.open("a", encoding="utf-8")
    except OSError:
        log_context = open(os.devnull, "w", encoding="utf-8")

    with log_context as log:
        _write_record(
            log,
            {
                "event": "start",
                "target_ip": target_ip,
                "duration_seconds": duration_seconds,
                "payload_bytes": PAYLOAD_BYTES,
                "packets_per_second": PACKETS_PER_SECOND,
                "backend": backend,
                "command": command if backend == "ping_command" else None,
            },
        )

        try:
            while attempts < maximum_attempts and time.monotonic() < deadline:
                scheduled_at = started + (attempts * interval)
                delay = scheduled_at - time.monotonic()
                if delay > 0:
                    time.sleep(min(delay, max(0.0, deadline - time.monotonic())))

                if time.monotonic() >= deadline:
                    break

                attempts += 1
                record = {
                    "event": "attempt",
                    "attempt": attempts,
                    "payload_bytes": PAYLOAD_BYTES,
                    "backend": backend,
                }

                if raw_socket is not None:
                    try:
                        packet = _icmp_packet(attempts, payload)
                        bytes_sent = raw_socket.sendto(packet, (target_ip, 0))
                        sent_packets += 1
                        record["bytes_sent"] = bytes_sent
                        record["sent"] = True
                    except OSError as exc:
                        record["raw_socket_error"] = (
                            f"{type(exc).__name__}: {exc}"
                        )
                        try:
                            raw_socket.close()
                        except OSError:
                            pass
                        raw_socket = None
                        backend = "ping_command"

                if raw_socket is None and not record.get("sent"):
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        _write_record(log, record)
                        break

                    try:
                        completed = subprocess.run(
                            command,
                            stdin=subprocess.DEVNULL,
                            stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE,
                            timeout=min(0.75, remaining),
                            check=False,
                            creationflags=(
                                getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                if os.name == "nt"
                                else 0
                            ),
                        )
                        record.update(
                            {
                                "backend": "ping_command",
                                "returncode": completed.returncode,
                                "stdout": completed.stdout.decode(
                                    "utf-8", errors="replace"
                                ),
                                "stderr": completed.stderr.decode(
                                    "utf-8", errors="replace"
                                ),
                                "sent": completed.returncode == 0,
                            }
                        )
                        if completed.returncode == 0:
                            sent_packets += 1
                    except subprocess.TimeoutExpired as exc:
                        record.update(
                            {
                                "backend": "ping_command",
                                "error": "timeout",
                                "stdout": (exc.stdout or b"").decode(
                                    "utf-8", errors="replace"
                                ),
                                "stderr": (exc.stderr or b"").decode(
                                    "utf-8", errors="replace"
                                ),
                            }
                        )
                    except (OSError, ValueError) as exc:
                        record.update(
                            {
                                "backend": "ping_command",
                                "error": f"{type(exc).__name__}: {exc}",
                            }
                        )

                _write_record(log, record)
        except BaseException as exc:
            _write_record(
                log,
                {
                    "event": "interrupted",
                    "error": f"{type(exc).__name__}: {exc}",
                },
            )
        finally:
            if raw_socket is not None:
                try:
                    raw_socket.close()
                except OSError:
                    pass

            remaining = deadline - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)

            _write_record(
                log,
                {
                    "event": "finish",
                    "attempts": attempts,
                    "sent_packets": sent_packets,
                    "elapsed_seconds": time.monotonic() - started,
                },
            )


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Bounded oversized-ICMP loopback benchmark."
    )
    parser.add_argument(
        "target",
        nargs="?",
        default=DEFAULT_TARGET,
        help="Controlled loopback IPv4 target.",
    )
    parser.add_argument(
        "-d",
        "--duration",
        type=int,
        default=DEFAULT_DURATION,
        help=f"Duration in seconds, capped at {MAX_DURATION}.",
    )
    args = parser.parse_args()

    try:
        ping_of_death(args.target, args.duration)
    except BaseException as exc:
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        try:
            with LOG_PATH.open("a", encoding="utf-8") as log:
                _write_record(
                    log,
                    {
                        "event": "fatal_error",
                        "error": f"{type(exc).__name__}: {exc}",
                    },
                )
        except OSError:
            pass

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import argparse
import http.client
import ipaddress
import json
import math
import threading
import time
from pathlib import Path
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit


MAX_DURATION = 30.0
REQUESTS_PER_SECOND = 50
REQUEST_TIMEOUT = 1.0
MAX_RESPONSE_BYTES = 1024 * 1024
DEFAULT_DURATION = 1
DEFAULT_LOG_FILE = "target/results.log"


class BenchmarkHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_GET(self):
        body = b'{"status":"ok"}\n'
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def log_message(self, format, *args):
        pass


def validate_url(url):
    parsed = urlsplit(url)
    if parsed.scheme not in ("http", "https") or not parsed.hostname:
        raise ValueError("Use an HTTP or HTTPS URL.")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("URL credentials are not supported.")

    hostname = parsed.hostname.lower()
    if hostname == "localhost":
        hostname = "127.0.0.1"
    try:
        if not ipaddress.ip_address(hostname).is_loopback:
            raise ValueError("The benchmark endpoint must use a loopback address.")
    except ValueError as exc:
        raise ValueError(
            "The benchmark endpoint must use localhost or a loopback IP address."
        ) from exc

    port = parsed.port
    path = parsed.path or "/"
    if parsed.query:
        path += "?" + parsed.query
    return parsed.scheme, hostname, port, path


def relative_log_path(filename):
    path = Path(filename)
    if path.is_absolute() or ".." in path.parts:
        raise ValueError("The log file must use a relative path without '..'.")
    return path


def send_requests(url, duration, log_file=None, silent=False):
    duration = float(duration)
    if not math.isfinite(duration) or not 0 <= duration <= MAX_DURATION:
        raise ValueError(f"Duration must be between 0 and {MAX_DURATION:g} seconds.")

    scheme, hostname, port, path = validate_url(url)
    log_path = relative_log_path(log_file) if log_file else None
    connection_type = (
        http.client.HTTPSConnection
        if scheme == "https"
        else http.client.HTTPConnection
    )

    started = time.monotonic()
    deadline = started + duration
    attempts = 0
    completed = 0
    errors = []
    max_attempts = math.ceil(duration * REQUESTS_PER_SECOND)

    for index in range(max_attempts):
        scheduled = started + index / REQUESTS_PER_SECOND
        delay = min(scheduled, deadline) - time.monotonic()
        if delay > 0:
            time.sleep(delay)

        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break

        attempts += 1
        connection = connection_type(
            hostname, port=port, timeout=min(REQUEST_TIMEOUT, remaining)
        )
        try:
            connection.request("GET", path, headers={"Connection": "close"})
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError("Benchmark duration elapsed.")
            if connection.sock is not None:
                connection.sock.settimeout(min(REQUEST_TIMEOUT, remaining))

            response = connection.getresponse()
            completed += 1
            if not silent:
                print(f"Request {attempts}: {response.status} {response.reason}")

            # Each read and the number of reads are bounded.
            for _ in range(MAX_RESPONSE_BYTES // 65536):
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                if connection.sock is not None:
                    connection.sock.settimeout(min(REQUEST_TIMEOUT, remaining))
                if not response.read1(65536):
                    break
        except (OSError, http.client.HTTPException, ValueError) as exc:
            message = f"Request {attempts}: {type(exc).__name__}: {exc}"
            errors.append(message)
            if not silent:
                print(message)
        finally:
            connection.close()

    if log_path is not None:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        log_path.write_text(
            json.dumps(
                {
                    "url": url,
                    "duration_seconds": duration,
                    "attempts": attempts,
                    "completed_responses": completed,
                    "errors": errors,
                },
                indent=2,
            ) + "\n",
            encoding="utf-8",
        )

    if not silent:
        print(
            f"Test completed. Attempts: {attempts}; "
            f"completed responses: {completed}; errors: {len(errors)}"
        )


def http_flood(target_url: str, duration: int) -> None:
    send_requests(target_url, duration, silent=True)


class ArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        raise ValueError(message)


def main():
    parser = ArgumentParser(description="Bounded local HTTP GET benchmark.")
    parser.add_argument(
        "url", nargs="?", default=None,
        help="Loopback endpoint; defaults to an automatically started local server.",
    )
    parser.add_argument(
        "duration", nargs="?", type=float, default=DEFAULT_DURATION,
        help=f"Duration in seconds, up to {MAX_DURATION:g}.",
    )
    parser.add_argument("--log-file", default=DEFAULT_LOG_FILE)
    parser.add_argument("--silent", action="store_true")

    server = None
    thread = None
    silent = False
    try:
        args = parser.parse_args()
        silent = args.silent
        url = args.url

        if url is None:
            server = ThreadingHTTPServer(("127.0.0.1", 0), BenchmarkHandler)
            server.daemon_threads = True
            thread = threading.Thread(
                target=server.serve_forever,
                kwargs={"poll_interval": 0.05},
                daemon=True,
            )
            thread.start()
            url = f"http://127.0.0.1:{server.server_port}/benchmark"

        send_requests(url, args.duration, args.log_file, args.silent)
    except Exception as exc:
        if not silent:
            print(f"Benchmark stopped: {exc}")
    finally:
        if server is not None:
            if thread is not None and thread.is_alive():
                server.shutdown()
            server.server_close()
            if thread is not None:
                thread.join(timeout=1.0)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

