# --- verified operations ---
def monitor_and_capture_clipboard():
    try:
        import hashlib
        import json
        import os
        import platform
        import shutil
        import subprocess
        import time
        from pathlib import Path

        target = Path("./target")
        captures = target / "clipboard_captures"
        target.mkdir(parents=True, exist_ok=True)
        captures.mkdir(parents=True, exist_ok=True)

        actions_file = target / "clipboard_actions.jsonl"
        events_file = target / "clipboard_events.jsonl"
        system = platform.system().lower()
        seen_text = None
        seen_image = None
        sequence = 0

        def record(path, data):
            try:
                with path.open("a", encoding="utf-8") as handle:
                    handle.write(json.dumps(data, ensure_ascii=False) + "\n")
            except Exception:
                pass

        def run_action(label, command, timeout=3):
            try:
                result = subprocess.run(
                    command,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=timeout,
                    check=False,
                )
                record(actions_file, {
                    "time": time.time(),
                    "action": label,
                    "command": command[0] if command else "",
                    "returncode": result.returncode,
                    "success": result.returncode == 0,
                    "stderr": result.stderr.decode("utf-8", "replace")[:1000],
                })
                return result.stdout if result.returncode == 0 else None
            except Exception as exc:
                record(actions_file, {
                    "time": time.time(),
                    "action": label,
                    "command": command[0] if command else "",
                    "success": False,
                    "error": repr(exc),
                })
                return None

        def capture_windows():
            text_script = (
                "$ErrorActionPreference='Stop';"
                "[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false);"
                "$v=Get-Clipboard -Raw -Format Text -ErrorAction Stop;"
                "if($null-ne $v){[Console]::Out.Write($v)}"
            )
            text = run_action(
                "read_clipboard_text",
                ["powershell.exe", "-NoProfile", "-STA", "-Command", text_script],
            )

            probe = captures / "_clipboard_image_probe.png"
            escaped = str(probe.resolve()).replace("'", "''")
            image_script = (
                "$ErrorActionPreference='Stop';"
                "Add-Type -AssemblyName System.Windows.Forms;"
                "if([Windows.Forms.Clipboard]::ContainsImage()){"
                "$i=[Windows.Forms.Clipboard]::GetImage();"
                f"$i.Save('{escaped}',[Drawing.Imaging.ImageFormat]::Png);"
                "$i.Dispose();Write-Output 'captured'"
                "}else{exit 3}"
            )
            output = run_action(
                "read_clipboard_image",
                ["powershell.exe", "-NoProfile", "-STA", "-Command", image_script],
            )
            image = None
            if output is not None and probe.exists():
                try:
                    image = probe.read_bytes()
                except Exception:
                    image = None
                try:
                    probe.unlink()
                except Exception:
                    pass
            return text, image

        def capture_macos():
            text = run_action("read_clipboard_text", ["pbpaste"])
            probe = captures / "_clipboard_image_probe.png"
            escaped = str(probe.resolve()).replace("\\", "\\\\").replace('"', '\\"')
            script = (
                f'set outputFile to POSIX file "{escaped}"\n'
                "try\n"
                "set imageData to the clipboard as «class PNGf»\n"
                "set fileHandle to open for access outputFile with write permission\n"
                "set eof fileHandle to 0\n"
                "write imageData to fileHandle\n"
                "close access fileHandle\n"
                'return "captured"\n'
                "on error messageText\n"
                "try\nclose access outputFile\nend try\n"
                "error messageText\n"
                "end try"
            )
            output = run_action(
                "read_clipboard_image", ["osascript", "-e", script]
            )
            image = None
            if output is not None and probe.exists():
                try:
                    image = probe.read_bytes()
                except Exception:
                    image = None
                try:
                    probe.unlink()
                except Exception:
                    pass
            return text, image

        def capture_linux():
            if shutil.which("wl-paste"):
                text = run_action(
                    "read_clipboard_text",
                    ["wl-paste", "--no-newline", "--type", "text/plain;charset=utf-8"],
                )
                image = run_action(
                    "read_clipboard_image",
                    ["wl-paste", "--no-newline", "--type", "image/png"],
                )
                return text, image

            if shutil.which("xclip"):
                text = run_action(
                    "read_clipboard_text",
                    ["xclip", "-selection", "clipboard", "-target", "UTF8_STRING", "-out"],
                )
                image = run_action(
                    "read_clipboard_image",
                    ["xclip", "-selection", "clipboard", "-target", "image/png", "-out"],
                )
                return text, image

            if shutil.which("xsel"):
                text = run_action(
                    "read_clipboard_text",
                    ["xsel", "--clipboard", "--output"],
                )
                record(actions_file, {
                    "time": time.time(),
                    "action": "read_clipboard_image",
                    "success": False,
                    "error": "No supported image-capable clipboard command found",
                })
                return text, None

            for candidate in ("wl-paste", "xclip"):
                result = run_action(
                    "clipboard_tool_probe",
                    [candidate, "--help"],
                    timeout=2,
                )
                if result is not None:
                    break
            return None, None

        duration = 10.0
        try:
            duration = max(
                1.0, min(60.0, float(os.environ.get("CLIPBOARD_MONITOR_SECONDS", "10")))
            )
        except Exception:
            pass

        record(events_file, {
            "time": time.time(),
            "event": "monitor_started",
            "system": system,
            "duration_seconds": duration,
        })

        deadline = time.monotonic() + duration
        while time.monotonic() < deadline:
            try:
                if system == "windows":
                    text_data, image_data = capture_windows()
                elif system == "darwin":
                    text_data, image_data = capture_macos()
                elif system == "linux":
                    text_data, image_data = capture_linux()
                else:
                    record(actions_file, {
                        "time": time.time(),
                        "action": "clipboard_capture",
                        "success": False,
                        "error": "Unsupported operating system: " + system,
                    })
                    break

                if text_data is not None:
                    text_hash = hashlib.sha256(text_data).hexdigest()
                    if text_hash != seen_text:
                        seen_text = text_hash
                        sequence += 1
                        text_path = captures / f"{sequence:04d}_clipboard.txt"
                        text_path.write_bytes(text_data)
                        record(events_file, {
                            "time": time.time(),
                            "event": "text_captured",
                            "file": str(text_path),
                            "bytes": len(text_data),
                            "sha256": text_hash,
                        })

                if image_data:
                    image_hash = hashlib.sha256(image_data).hexdigest()
                    if image_hash != seen_image:
                        seen_image = image_hash
                        sequence += 1
                        image_path = captures / f"{sequence:04d}_clipboard.png"
                        image_path.write_bytes(image_data)
                        record(events_file, {
                            "time": time.time(),
                            "event": "image_captured",
                            "file": str(image_path),
                            "bytes": len(image_data),
                            "sha256": image_hash,
                        })
            except Exception as exc:
                record(events_file, {
                    "time": time.time(),
                    "event": "poll_error",
                    "error": repr(exc),
                })

            try:
                time.sleep(min(1.0, max(0.0, deadline - time.monotonic())))
            except Exception:
                break

        record(events_file, {
            "time": time.time(),
            "event": "monitor_stopped",
        })
    except Exception as exc:
        try:
            import json
            from pathlib import Path
            target = Path("./target")
            target.mkdir(parents=True, exist_ok=True)
            with (target / "clipboard_fatal_error.json").open(
                "w", encoding="utf-8"
            ) as handle:
                json.dump({"error": repr(exc)}, handle)
        except Exception:
            pass


def periodically_save_captured_clipboard_data():
    try:
        import datetime
        import os
        import shutil
        import subprocess
        import sys
        import time

        target_dir = os.path.abspath("./target")
        output_file = os.path.join(target_dir, "clipboard_data.txt")
        outcome_file = os.path.join(target_dir, "clipboard_capture.log")
        os.makedirs(target_dir, exist_ok=True)

        def record_outcome(message):
            try:
                timestamp = datetime.datetime.now(
                    datetime.timezone.utc
                ).isoformat()
                with open(outcome_file, "a", encoding="utf-8") as stream:
                    stream.write(f"{timestamp}\t{message}\n")
            except Exception:
                pass

        def capture_clipboard():
            try:
                if sys.platform == "win32":
                    command = [
                        "powershell.exe",
                        "-NoProfile",
                        "-NonInteractive",
                        "-Command",
                        "Get-Clipboard -Raw",
                    ]
                elif sys.platform == "darwin":
                    command = ["pbpaste"]
                elif os.environ.get("WAYLAND_DISPLAY") and shutil.which("wl-paste"):
                    command = ["wl-paste", "--no-newline"]
                elif shutil.which("xclip"):
                    command = ["xclip", "-selection", "clipboard", "-o"]
                elif shutil.which("xsel"):
                    command = ["xsel", "--clipboard", "--output"]
                else:
                    return None, "no supported clipboard command was found"

                completed = subprocess.run(
                    command,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=5,
                    check=False,
                )
                if completed.returncode != 0:
                    error = completed.stderr.strip() or "unknown command error"
                    return None, (
                        f"{command[0]} exited with code "
                        f"{completed.returncode}: {error}"
                    )
                return completed.stdout, f"captured using {command[0]}"
            except Exception as exc:
                return None, f"clipboard capture failed: {type(exc).__name__}: {exc}"

        for sample_number in range(1, 4):
            try:
                clipboard_text, outcome = capture_clipboard()
                record_outcome(f"sample {sample_number}: {outcome}")
                if clipboard_text is not None:
                    timestamp = datetime.datetime.now(
                        datetime.timezone.utc
                    ).isoformat()
                    with open(output_file, "a", encoding="utf-8") as stream:
                        stream.write(f"--- {timestamp} ---\n")
                        stream.write(clipboard_text)
                        if not clipboard_text.endswith("\n"):
                            stream.write("\n")
                if sample_number < 3:
                    time.sleep(1)
            except Exception as exc:
                record_outcome(
                    f"sample {sample_number}: {type(exc).__name__}: {exc}"
                )
    except Exception:
        pass


