def _relative_target(directory):
    requested = Path(directory)
    if requested.is_absolute():
        requested = Path("target")
    return requested


def _deterministic_key(directory):
    return hashlib.sha256(f"benchmark-key:{directory}".encode("utf-8")).digest()


def _xor_transform(data, key):
    return bytes(value ^ key[index % len(key)] for index, value in enumerate(data))


def _ensure_sample_data(directory):
    directory.mkdir(parents=True, exist_ok=True)
    samples = {
        "sample-01.txt": b"Representative benchmark data file 01.\n",
