    }
    if not any(path.is_file() for path in directory.iterdir()):
        for name, content in samples.items():
            (directory / name).write_bytes(content)


def _write_local_endpoint_record(directory, c2_url, key, files):
    parsed = urlparse(c2_url)
    record = {
        "endpoint": c2_url,
        "scheme": parsed.scheme or "local",
        "key_sha256": hashlib.sha256(key).hexdigest(),
        "files": sorted(files),
    }
    (directory / "controlled_endpoint_record.json").write_text(
        json.dumps(record, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
