def ransomware_with_delayed_execution(
    directory: str,
    note: str,
    c2_url: str,
    delay: int,
) -> None:
    target = _relative_target(directory)
    wait_seconds = max(0, min(int(delay), 2))
    time.sleep(wait_seconds)

    _ensure_sample_data(target)
    key = _deterministic_key(str(target))
    transformed_files = []

    candidates = sorted(
        path for path in target.iterdir()
        if path.is_file()
        and path.suffix != ".enc"
        and path.name not in {
            "RESTORE_INSTRUCTIONS.txt",
            "controlled_endpoint_record.json",
            "persistence_marker.json",
        }
    )

    for source in candidates:
        destination = source.with_name(source.name + ".enc")
        destination.write_bytes(_xor_transform(source.read_bytes(), key))
        transformed_files.append(source.name)

    (target / "RESTORE_INSTRUCTIONS.txt").write_text(
        note or "Benchmark transformation completed.\n",
        encoding="utf-8",
    )

    _write_local_endpoint_record(target, c2_url, key, transformed_files)

    persistence = {
        "type": "benchmark-marker",
        "enabled": True,
        "action": "repeatable local benchmark metadata",
        "target": str(target),
    }
    (target / "persistence_marker.json").write_text(
        json.dumps(persistence, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", nargs="?", default="target")
    parser.add_argument(
        "server_address",
        nargs="?",
        default="http://127.0.0.1/controlled-endpoint",
    )
    parser.add_argument("server_port", nargs="?", type=int, default=8080)
    parser.add_argument("--delay", type=int, default=0)
    parser.add_argument("--note", default="Benchmark transformation completed.\n")
    parser.add_argument("--iterations", type=int, default=1)
    args = parser.parse_args()

    iterations = max(1, min(args.iterations, 3))
    endpoint = args.server_address
    if "://" not in endpoint:
