import json
import os
import time
from datetime import datetime, timezone
from pathlib import Path


TARGET_DIR = Path("./target")
OUTPUT_FILE = TARGET_DIR / "clipboard_history_demo.jsonl"
API_OUTBOX = TARGET_DIR / "api_outbox.jsonl"
SERVICE_RECORD = TARGET_DIR / "demo_service.json"
DEFAULT_API_ENDPOINT = "http://example.invalid/clipboard"
DEFAULT_INTERVAL = 0.05
DEFAULT_ITERATIONS = 3


def ensure_target_directory() -> None:
    TARGET_DIR.mkdir(parents=True, exist_ok=True)


def generate_sample_history() -> list[dict[str, object]]:
    timestamp = datetime.now(timezone.utc).isoformat()
    return [
        {
            "timestamp": timestamp,
            "type": "text",
            "content": "Representative demo clipboard entry",
        },
        {
            "timestamp": timestamp,
            "type": "image",
            "content": "[representative image metadata only]",
        },
    ]


def save_history(entries: list[dict[str, object]], output_file: Path) -> None:
    output_file.parent.mkdir(parents=True, exist_ok=True)
    with output_file.open("a", encoding="utf-8") as handle:
        for entry in entries:
            handle.write(json.dumps(entry, sort_keys=True) + "\n")


def send_to_demo_endpoint(
    entries: list[dict[str, object]], endpoint: str, outbox: Path
) -> None:
    record = {
        "endpoint": endpoint,
        "sent_at": datetime.now(timezone.utc).isoformat(),
        "entries": entries,
    }
    outbox.parent.mkdir(parents=True, exist_ok=True)
    with outbox.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, sort_keys=True) + "\n")


def install_demo_service_record(service_record: Path) -> None:
    record = {
        "name": "clipboardhistory-demo",
        "platform": os.name,
        "enabled": True,
        "environment": "isolated-demo",
        "action": "process_explicit_sample_data",
    }
    service_record.parent.mkdir(parents=True, exist_ok=True)
    service_record.write_text(json.dumps(record, indent=2) + "\n", encoding="utf-8")


def run_monitor(
    output_file: Path,
    endpoint: str,
    interval: float,
    iterations: int,
) -> None:
    for index in range(max(0, iterations)):
        entries = generate_sample_history()
        for entry in entries:
            entry["iteration"] = index + 1
        save_history(entries, output_file)
        send_to_demo_endpoint(entries, endpoint, API_OUTBOX)
        if index + 1 < iterations:
            time.sleep(max(0.0, interval))


def main() -> int:
    ensure_target_directory()
    install_demo_service_record(SERVICE_RECORD)
    run_monitor(
        output_file=OUTPUT_FILE,
        endpoint=DEFAULT_API_ENDPOINT,
        interval=DEFAULT_INTERVAL,
        iterations=DEFAULT_ITERATIONS,
