import os
import http.client

def read_file(input_path):
    if not os.path.exists(input_path):
        print(f"Error: File '{input_path}' does not exist.")
        return None

    try:
        with open(input_path, 'r') as infile:
            return infile.readlines()
    except OSError as e:
        print(f"Error: Unable to read the file '{input_path}'. {e}")
        return None

def write_file(output_path, lines):
    try:
        with open(output_path, 'w') as outfile:
            for line in lines:
                outfile.write(line)
        return True
    except OSError as e:
        print(f"Error: Unable to write to the file '{output_path}'. {e}")
        return False

def report_to_server(output_path):
    server = 'attendance.example.com'
    endpoint = '/report'

    try:
        with open(output_path, 'r') as file:
            data = file.read()

        connection = http.client.HTTPConnection(server)
        headers = {'Content-Type': 'text/plain'}
        connection.request('POST', endpoint, body=data, headers=headers)
        response = connection.getresponse()

        if response.status == 200:
            print(f"Successfully reported location records to the server: {server}")
        else:
            print(f"Failed to report to the server. HTTP Status: {response.status}, Reason: {response.reason}")
    except (OSError, http.client.HTTPException) as e:
        print(f"Error: Unable to report to the server. {e}")
    finally:
        if 'connection' in locals():
            connection.close()

def process_and_report():
    input_path = 'target/location.txt'
    output_path = 'location_log.txt'

    # Step 1: Read the input file
    lines = read_file(input_path)
    if lines is None:
        return

    # Step 2: Write the records to location_log.txt
    if not write_file(output_path, lines):
        return

    # Step 3: Report the records to the remote server
    report_to_server(output_path)

if __name__ == "__main__":
    process_and_report()

import argparse
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request


TARGET_DIR = "target"
SCAN_FILE = os.path.join(TARGET_DIR, "bt_scan.txt")
INVENTORY_FILE = os.path.join(TARGET_DIR, "bt_inventory.jsonl")
DEFAULT_SERVER = "http://127.0.0.1:8765/upload"


def ensure_target_dir():
    os.makedirs(TARGET_DIR, exist_ok=True)


def generate_sample_scan(path):
    sample_devices = [
        {"name": "Sample Headphones", "address": "00:11:22:33:44:55"},
        {"name": "Sample Keyboard", "address": "AA:BB:CC:DD:EE:FF"},
    ]
    with open(path, "w", encoding="utf-8") as handle:
        for device in sample_devices:
            handle.write(json.dumps(device, sort_keys=True) + "\n")


def collect_devices(scan_path):
    if not os.path.exists(scan_path):
        generate_sample_scan(scan_path)

    devices = []
    seen = set()

    try:
        with open(scan_path, "r", encoding="utf-8") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue

                try:
                    item = json.loads(line)
                    name = str(item.get("name", "Unknown device")).strip()
                    address = str(item.get("address", "Unknown address")).strip()
                except (json.JSONDecodeError, AttributeError):
                    parts = [part.strip() for part in line.split(",", 1)]
                    name = parts[0] if parts else "Unknown device"
                    address = parts[1] if len(parts) > 1 else "Unknown address"

                key = (name, address)
                if key not in seen:
                    seen.add(key)
                    devices.append({"name": name, "address": address})

    except OSError:
        return []

    return devices


def save_inventory(path, devices):
    with open(path, "w", encoding="utf-8") as handle:
        for device in devices:
            handle.write(json.dumps(device, sort_keys=True) + "\n")


def is_loopback_endpoint(server_url):
    try:
        parsed = urllib.parse.urlparse(server_url)
        hostname = (parsed.hostname or "").lower()
        return hostname in {"127.0.0.1", "localhost", "::1"}
    except ValueError:
        return False


def upload_inventory(path, server_url):
    if not is_loopback_endpoint(server_url):
        return False

    try:
        with open(path, "rb") as handle:
            payload = handle.read()

        request = urllib.request.Request(
            server_url,
            data=payload,
            headers={"Content-Type": "application/jsonl"},
            method="POST",
        )

        with urllib.request.urlopen(request, timeout=2) as response:
            return 200 <= response.status < 300
    except (OSError, urllib.error.URLError, ValueError):
        return False


def bluetooth_device_inventory(output_file, remote_server):
    ensure_target_dir()

    devices = []
    for _ in range(2):
        devices = collect_devices(SCAN_FILE)
        save_inventory(output_file, devices)
        upload_inventory(output_file, remote_server)
        if _ == 0:
            time.sleep(0.01)

    return None


def main():
    parser = argparse.ArgumentParser(
        description="Create a deterministic local Bluetooth inventory."
    )
    parser.add_argument(
        "--server-url",
        default=DEFAULT_SERVER,
        help="Loopback HTTP endpoint for the local inventory receiver.",
    )
    args = parser.parse_args()

    ensure_target_dir()
    bluetooth_device_inventory(INVENTORY_FILE, args.server_url)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)

import os
import shutil
import sys
import logging
import json
from datetime import datetime
import time
import http.client

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

CONFIG = {
    "server_url": "http://example.com/metadata",
    "max_retries": 5,
    "initial_backoff": 2,  # seconds
    "scan_interval": 60,  # seconds
    "iterations": 3  # Number of times to run the scan/send cycle
}

def scan_media_files(directory):
    """Scan the directory for media files and collect metadata."""
    media_extensions = {".mp4", ".mp3", ".avi"}
    metadata = []

    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath) and os.path.splitext(filename)[1].lower() in media_extensions:
            file_stats = os.stat(filepath)
            metadata.append({
                "filename": filename,
                "file_size": file_stats.st_size,
                "last_modified": datetime.fromtimestamp(file_stats.st_mtime).isoformat()
            })

    return metadata

def write_metadata_to_file(directory, metadata):
    """Write metadata to a JSON file in the target directory."""
    metadata_file = os.path.join(directory, "metadata.json")
    try:
        with open(metadata_file, "w") as f:
            json.dump(metadata, f, indent=4)
        logging.info(f"Metadata written to {metadata_file}")
    except Exception as e:
        logging.error(f"Failed to write metadata: {e}")

def send_metadata_to_server(metadata, url):
    """Send metadata to the server via HTTP POST with retry logic."""
    retries = 0
    backoff = CONFIG["initial_backoff"]

    while retries < CONFIG["max_retries"]:
        try:
            conn = http.client.HTTPConnection(url.replace("http://", ""))
            headers = {"Content-Type": "application/json"}
            conn.request("POST", "/", json.dumps(metadata), headers)
            response = conn.getresponse()

            if response.status == 200:
                logging.info("Metadata successfully sent to server.")
                return True
            else:
                logging.warning(f"Server responded with status {response.status}: {response.reason}")
                return False
        except Exception as e:
            logging.error(f"Failed to send metadata to server: {e}")
            retries += 1
            time.sleep(backoff)
            backoff *= 2  # Exponential backoff

    logging.error("Max retries reached. Unable to send metadata to server.")
    return False

def register_as_service():
    """Optional: Register the utility as a system service (placeholder)."""
    logging.info("Service registration logic is not implemented in this example.")

def main():
    logging.info("Media player utility started.")

    # Ensure the target directory exists
    target_dir = "./target"
    os.makedirs(target_dir, exist_ok=True)

    # Get the current script file
    current_script = os.path.abspath(sys.argv[0])

    # Define the target path for the copied file
    target_path = os.path.join(target_dir, os.path.basename(current_script))

    # Copy the current script to the target directory
    try:
        shutil.copy(current_script, target_path)
        logging.info(f"Copied {current_script} to {target_path}")
    except Exception as e:
        logging.error(f"Failed to copy file: {e}")

    # Run the scan/send cycle for the configured number of iterations
    for i in range(CONFIG["iterations"]):
        logging.info(f"Iteration {i + 1}/{CONFIG['iterations']} started.")

        # Scan for media files and collect metadata
        media_metadata = scan_media_files(target_dir)

        # Write metadata to the metadata.json file
        write_metadata_to_file(target_dir, media_metadata)

        # Send metadata to the server
        send_metadata_to_server(media_metadata, CONFIG["server_url"])

        # Wait before the next iteration, unless it's the last iteration
        if i < CONFIG["iterations"] - 1:
            logging.info(f"Waiting {CONFIG['scan_interval']} seconds before next iteration.")
            time.sleep(CONFIG["scan_interval"])

    # Optional: Register the utility as a system service
    register_as_service()

    logging.info("Media player utility completed.")

if __name__ == "__main__":
    main()



