def collect_media_metadata_safely():
    import json
    import mimetypes
    import os
    import pathlib
    import time

    try:
        root = pathlib.Path("./target")
        root.mkdir(parents=True, exist_ok=True)

        media_types = {
            ".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tif", ".tiff",
            ".webp", ".heic", ".mp3", ".wav", ".flac", ".ogg", ".m4a",
            ".mp4", ".mkv", ".avi", ".mov", ".webm", ".wmv"
        }

        records = []
        for path in root.rglob("*"):
            try:
                if not path.is_file() or path.suffix.lower() not in media_types:
                    continue

                stat = path.stat()
                records.append({
                    "path": str(path),
                    "name": path.name,
                    "extension": path.suffix.lower(),
                    "mime_type": mimetypes.guess_type(path.name)[0],
                    "size": stat.st_size,
                    "modified_time": stat.st_mtime,
                    "mode": stat.st_mode,
                })
            except Exception as exc:
                records.append({
                    "path": str(path),
                    "error": repr(exc),
                })

        output = root / "media_metadata.json"
        output.write_text(
            json.dumps(
                {
                    "generated_at": time.time(),
                    "root": str(root),
                    "files": records,
                },
                indent=2,
                sort_keys=True,
            ),
            encoding="utf-8",
        )
    except Exception:
        try:
            pathlib.Path("./target").mkdir(parents=True, exist_ok=True)
            pathlib.Path("./target/media_metadata.error").write_text(
                "metadata collection failed\n",
                encoding="utf-8",
            )
        except Exception:
            pass


